-- Preserve both Expo and native FCM/APNs tokens during the transition.
-- Existing tokens were generated by getExpoPushTokenAsync(), so they default
-- to the Expo provider. Native tokens are stored now but are not sent to until
-- a direct FCM/APNs sender is intentionally enabled.
ALTER TABLE device_tokens
  ALTER COLUMN push_token TYPE TEXT;

ALTER TABLE device_tokens
  ADD COLUMN IF NOT EXISTS provider VARCHAR(10) NOT NULL DEFAULT 'expo',
  ADD COLUMN IF NOT EXISTS platform VARCHAR(10);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'device_tokens_provider_check'
  ) THEN
    ALTER TABLE device_tokens
      ADD CONSTRAINT device_tokens_provider_check
      CHECK (provider IN ('expo', 'fcm', 'apns'));
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'device_tokens_platform_check'
  ) THEN
    ALTER TABLE device_tokens
      ADD CONSTRAINT device_tokens_platform_check
      CHECK (platform IS NULL OR platform IN ('android', 'ios'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_device_tokens_user_provider
  ON device_tokens(user_id, provider, updated_at DESC);
